// Decides whether the email must be sent in this run.
// The manual path always continues. The scheduled path continues only when the
// current hour and weekday in America/Bogota match send_hour and send_days.
const config = {};
for (const row of $('Config').all()) {
  const key = String(row.json.key ?? '').trim();
  if (key) config[key] = String(row.json.value ?? '').trim();
}

const manual = $('Manual Trigger').isExecuted;

const parts = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Bogota',
  weekday: 'short',
  hour: 'numeric',
  hourCycle: 'h23',
}).formatToParts(new Date());
const hour = Number(parts.find((p) => p.type === 'hour').value);
const weekday = parts.find((p) => p.type === 'weekday').value.toLowerCase();

const sendHour = Number(config.send_hour);
const sendDays = (config.send_days ?? '')
  .toLowerCase()
  .split(',')
  .map((d) => d.trim())
  .filter(Boolean);

const hourOk = config.send_hour !== undefined && config.send_hour !== '' && sendHour === hour;
const dayOk = sendDays.includes('all') || sendDays.includes(weekday);

if (!manual && !(hourOk && dayOk)) {
  return [];
}

return [{ json: { config, manual, hour, weekday } }];

// Builds the plan of the run from the active rows of Users: the cleaned
// recipient list of each row, the languages to fetch and the distinct variants
// (language, level, audience) that need a reflection.
const norm = (v) => String(v ?? '').trim();
const lower = (v) => norm(v).toLowerCase();
const isTrue = (v) => norm(v).toUpperCase() === 'TRUE';

// Allowed values come from Config. A missing or empty list falls back to the
// default. Languages can only be restricted: each one needs its feed code and
// labels in the workflow.
const config = $('Schedule Check').first().json.config;
const list = (key, fallback, fix) => {
  const values = norm(config[key]).split(',').map((v) => fix(v.trim())).filter(Boolean);
  return values.length ? [...new Set(values)] : fallback;
};
const lowerCase = (v) => v.toLowerCase();
const KNOWN_LANGUAGES = ['en', 'es', 'both'];
const LANGUAGES = list('languages', KNOWN_LANGUAGES, lowerCase).filter((l) => KNOWN_LANGUAGES.includes(l));
const LEVELS = list('levels', ['B1', 'B2', 'C1'], (v) => v.toUpperCase());
const AUDIENCES = list('audiences', ['general', 'men', 'women'], lowerCase);

const rows = [];
const skipped = [];
const variantsByKey = {};

for (const { json: u } of $('Users').all()) {
  if (!isTrue(u.active)) continue;

  const language = lower(u.language);
  const audience = lower(u.audience);
  const needsEn = language === 'en' || language === 'both';
  const needsEs = language === 'es' || language === 'both';
  const level = needsEn ? norm(u.level).toUpperCase() : '-';

  // A value outside the Config lists matches nothing: the row is left out and listed here.
  if (
    !LANGUAGES.includes(language) ||
    !AUDIENCES.includes(audience) ||
    (needsEn && !LEVELS.includes(level))
  ) {
    skipped.push({ rowNumber: u.row_number, language, level, audience });
    continue;
  }

  const recipients = [
    ...new Set(
      norm(u.emails)
        .split(',')
        .map((e) => e.trim().toLowerCase())
        .filter((e) => e && e.includes('@')),
    ),
  ];

  const variantKeys = [];
  if (needsEn) variantKeys.push(`en|${level}|${audience}`);
  if (needsEs) variantKeys.push(`es|-|${audience}`);

  // Rows with no valid address send nothing, so they ask for no reflection.
  if (recipients.length) {
    for (const key of variantKeys) {
      const [lang, lvl, aud] = key.split('|');
      variantsByKey[key] ??= { key, language: lang, level: lvl, audience: aud };
    }
  }

  rows.push({ rowNumber: u.row_number, language, level, audience, recipients, variantKeys });
}

const variants = Object.values(variantsByKey);
const languages = ['en', 'es'].filter((l) => variants.some((v) => v.language === l));

return [{ json: { rows, languages, variants, skipped, allowed: { languages: LANGUAGES, levels: LEVELS, audiences: AUDIENCES } } }];

// One Evangelizo request per needed language and per part of the gospel:
// text, short reference and liturgical day. The date is today in America/Bogota.
const { languages } = $('Build Plan').first().json;

const date = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Bogota',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
})
  .format(new Date())
  .replaceAll('-', '');

const FEED_LANG = { en: 'AM', es: 'SP' };
const PARTS = [
  { part: 'text', type: 'reading', content: 'GSP' },
  { part: 'reference', type: 'reading_st', content: 'GSP' },
  { part: 'liturgicalDay', type: 'liturgic_t' },
];

return languages.flatMap((language) =>
  PARTS.map(({ part, type, content }) => ({
    json: {
      language,
      part,
      query: { date, lang: FEED_LANG[language], type, ...(content ? { content } : {}) },
    },
  })),
);

// Builds one Gospel object per language from the Evangelizo answers, which are
// HTML fragments. A failed text call or an empty text gives ok = false.
const ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
  aacute: 'á', eacute: 'é', iacute: 'í', oacute: 'ó', uacute: 'ú',
  Aacute: 'Á', Eacute: 'É', Iacute: 'Í', Oacute: 'Ó', Uacute: 'Ú',
  ntilde: 'ñ', Ntilde: 'Ñ', uuml: 'ü', Uuml: 'Ü', iexcl: '¡', iquest: '¿',
  laquo: '«', raquo: '»', lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”',
  ndash: '–', mdash: '—', hellip: '…', copy: '©',
};
const decode = (s) =>
  s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, code) => {
    if (code[0] !== '#') return ENTITIES[code] ?? match;
    const point = code[1].toLowerCase() === 'x' ? parseInt(code.slice(2), 16) : Number(code.slice(1));
    return Number.isInteger(point) && point > 0 && point <= 0x10ffff ? String.fromCodePoint(point) : match;
  });

// Tags out, entities decoded, runs of spaces collapsed.
const clean = (html) => decode(html.replace(/<[^>]*>/g, '')).replace(/\s+/g, ' ').trim();
// One cleaned line per <br />, empty lines dropped.
const lines = (html) => html.split(/<br\s*\/?>/i).map(clean).filter(Boolean);

// The HTTP node returns one result per request, in the same order.
const requests = $('Gospel Requests').all();
const results = $input.all();
const inOrder = results.length === requests.length;

const raw = {};
requests.forEach(({ json: request }, i) => {
  const result = inOrder ? results[i].json : {};
  const body = !result.error && typeof result.data === 'string' ? result.data : '';
  (raw[request.language] ??= {})[request.part] = body;
});

const gospels = {};
for (const [language, parts] of Object.entries(raw)) {
  // The gospel ends at the first double <br />. The copyright line and the
  // subscription line come after it.
  const [reading, ...rest] = parts.text.split(/<br\s*\/?>\s*<br\s*\/?>/i);
  const text = lines(reading).join('\n');
  const attribution = lines(rest.join('<br />'))[0] ?? '';

  gospels[language] = {
    language,
    liturgicalDay: clean(parts.liturgicalDay),
    reference: clean(parts.reference).replace(/\.$/, ''),
    text,
    attribution,
    ok: text !== '',
  };
}

return [{ json: { date: requests[0]?.json.query.date ?? '', gospels } }];

// Builds one Ollama request per needed language for the apologetic note, from
// the gospel text of that language. The note does not depend on level or
// audience. With apologetics = off in Config, or a gospel that is not ok, the
// language gets no request.
const { config } = $('Schedule Check').first().json;
const model = config.ollama_model || 'gemma4:12b';
// Only "off" disables the step. A missing key or any other value counts as on.
const enabled = String(config.apologetics ?? '').trim().toLowerCase() !== 'off';
const { languages } = $('Build Plan').first().json;
const { gospels } = $('Build Gospels').first().json;

// The schema makes Ollama write the answer in this exact shape.
const string = { type: 'string' };
const format = {
  type: 'object',
  properties: { needed: { type: 'boolean' }, context: string, meaning: string },
  required: ['needed', 'context', 'meaning'],
};

return languages.map((language) => {
  const gospel = gospels[language];
  const wantsNote = enabled && Boolean(gospel?.ok);
  if (!wantsNote) return { json: { language, wantsNote } };

  // One English note serves every level, so it is always written in simple English.
  const target =
    language === 'es'
      ? 'Spanish, in the plain and warm Spanish of Latin America'
      : 'simple English at CEFR level B1, with short sentences and common words';

  const prompt = [
    'You are a Catholic apologist who explains the gospel of the day to ordinary readers of a daily email.',
    'Decide whether this passage needs a short note to be understood, and write the note only when it does.',
    `Write "context" and "meaning" in ${target}.`,
    '',
    'Form:',
    '- "needed": true only when the passage has a custom, an image, an expression or a saying that a modern reader would likely misread or find shocking. false when the passage is clear on its own.',
    '- "context": one sentence with the historical or cultural background that a reader needs to read the passage well.',
    '- "meaning": one sentence that says what the passage means in Catholic teaching, in plain words.',
    '- When "needed" is false, leave "context" and "meaning" as empty strings.',
    '',
    'Rules:',
    '- Each of the two sentences has at most 35 words.',
    '- Use only the passage given below. Do not quote, cite or mention any bible verse or bible story that is not in it.',
    '- No citations: do not name the Catechism, a council, a pope, a saint, an author or any document, and give no paragraph numbers.',
    '- Do not invent words of Jesus or of God.',
    '- No greetings, no titles and no markdown.',
    '',
    'Answer with JSON only, in this shape:',
    '{"needed": true, "context": "...", "meaning": "..."}',
    '',
    `Reference: ${gospel.reference}`,
    'Passage:',
    gospel.text,
  ].join('\n');

  return {
    json: {
      language,
      wantsNote,
      request: { model, prompt, format, stream: false, think: false },
    },
  };
});

// Builds one Note object per language from the Ollama answers. A note is valid
// when needed is a boolean and, if it is true, context and meaning are filled
// in with at most 300 characters each. A failed call, invalid JSON or an
// invalid answer gives ok = false, and the section is left out of the email.
const MAX_LENGTH = 300;
const text = (v) => (typeof v === 'string' ? v.trim() : '');

// The loop returns one result per language, in the same order.
const requests = $('Apologetics Prompts').all();
const results = $input.all();
const inOrder = results.length === requests.length;

const notes = {};
requests.forEach(({ json: { language, wantsNote } }, i) => {
  const note = { language, needed: false, context: '', meaning: '', ok: false };
  if (inOrder && wantsNote) {
    try {
      const answer = JSON.parse(results[i].json.response) ?? {};
      const context = text(answer.context);
      const meaning = text(answer.meaning);
      const fits = (line) => line !== '' && line.length <= MAX_LENGTH;
      if (answer.needed === false) {
        // The passage is clear on its own: context and meaning are ignored.
        note.ok = true;
      } else if (answer.needed === true && fits(context) && fits(meaning)) {
        Object.assign(note, { needed: true, context, meaning, ok: true });
      }
    } catch (error) {
      // Failed call or invalid JSON: the email goes out without the note.
    }
  }
  notes[language] = note;
});

return [{ json: { notes } }];

// Builds one Ollama request per variant (language, level, audience), from the
// gospel text of that language. A variant whose gospel is not ok gets no request.
// When the language has a valid and needed apologetic note, its two lines go
// into the prompt, so the reflection builds on the same meaning.
const { config } = $('Schedule Check').first().json;
const model = config.ollama_model || 'gemma4:12b';
const { variants } = $('Build Plan').first().json;
const { gospels } = $('Build Gospels').first().json;
const { notes } = $('Apply Apologetics').first().json;

const AUDIENCES = {
  general: 'adults of any age and walk of life',
  men: 'men: speak to their life as sons, brothers, friends, husbands, fathers and workers',
  women: 'women: speak to their life as daughters, sisters, friends, wives, mothers and workers',
};

// The schema makes Ollama write the answer in this exact shape.
const string = { type: 'string' };
const format = {
  type: 'object',
  properties: {
    dialogue: {
      type: 'array',
      minItems: 3,
      maxItems: 3,
      items: {
        type: 'object',
        properties: { question: string, answer: string },
        required: ['question', 'answer'],
      },
    },
    application: string,
    action: string,
    prayer: string,
    reflection_question: string,
    phrase: string,
  },
  required: ['dialogue', 'application', 'action', 'prayer', 'reflection_question', 'phrase'],
};

return variants.map((variant) => {
  const gospel = gospels[variant.language];
  const wantsReflection = Boolean(gospel?.ok);
  if (!wantsReflection) return { json: { variant, wantsReflection } };

  const target =
    variant.language === 'es'
      ? 'Spanish, in the plain and warm Spanish of Latin America'
      : `English at CEFR level ${variant.level}, with vocabulary and grammar that fit that level`;
  const audience = AUDIENCES[variant.audience] ?? variant.audience;
  const note = notes[variant.language];
  const noteLines =
    note?.ok && note.needed
      ? [
          '',
          'Note on the passage. The reader sees it before your reflection. Keep your answers consistent with it, and do not repeat it word for word:',
          `Context: ${note.context}`,
          `Meaning: ${note.meaning}`,
        ]
      : [];

  const prompt = [
    'You write a short reflection on the Catholic gospel of the day for a daily email.',
    'It helps ordinary people understand the passage in an easy way and apply it to real life today.',
    `Write every field in ${target}.`,
    `The readers are ${audience}.`,
    '',
    'Form:',
    '- "dialogue": exactly 3 question-and-answer pairs about this passage. Each question is one an honest reader would ask after reading it, in the first person. Each answer has 2 or 3 sentences and explains the passage in simple words. The first pair is about what happens in the passage, the second about what it means, the third about what it asks of the reader.',
    '- The answers are the voice of a guide who explains the passage. They are never God or Jesus speaking in the first person.',
    '- "application": one paragraph that brings the passage to the daily life of these readers, with concrete situations.',
    '- "action": one concrete and small action the reader can do today.',
    '- "prayer": a short and direct prayer of 3 to 5 lines, in the first person singular, spoken to God. Separate the lines with \\n.',
    '- "reflection_question": one question for the reader to think about during the day.',
    '- "phrase": one short line to remember, in your own words.',
    '',
    'Rules:',
    '- Use only the passage given below. Do not quote, cite or mention any bible verse or bible story that is not in it.',
    '- When you quote the passage, copy the words exactly as they are in the text below.',
    '- Do not invent words of Jesus or of God.',
    '- No greetings, no titles and no markdown.',
    '',
    'Answer with JSON only, in this shape:',
    '{"dialogue": [{"question": "...", "answer": "..."}, {"question": "...", "answer": "..."}, {"question": "...", "answer": "..."}], "application": "...", "action": "...", "prayer": "...", "reflection_question": "...", "phrase": "..."}',
    '',
    `Reference: ${gospel.reference}`,
    'Passage:',
    gospel.text,
    ...noteLines,
  ].join('\n');

  return {
    json: {
      variant,
      wantsReflection,
      request: { model, prompt, format, stream: false, think: false },
    },
  };
});

// Puts each Ollama answer into its variant. A reflection is valid only with
// exactly 3 question-and-answer pairs and the other five fields filled in.
// A failed call, invalid JSON or an incomplete answer gives aiOk = false.
const text = (v) => (typeof v === 'string' ? v.trim() : '');

// The loop returns one result per variant, in the same order.
const requests = $('Reflection Prompts').all();
const results = $input.all();
const inOrder = results.length === requests.length;

return requests.map(({ json: { variant, wantsReflection } }, i) => {
  let reflection = null;
  if (inOrder && wantsReflection) {
    try {
      const answer = JSON.parse(results[i].json.response) ?? {};
      const pairs = Array.isArray(answer.dialogue) ? answer.dialogue : [];
      const dialogue = pairs
        .map((p) => ({ question: text(p?.question), answer: text(p?.answer) }))
        .filter((p) => p.question && p.answer);
      const candidate = {
        dialogue,
        application: text(answer.application),
        action: text(answer.action),
        prayer: text(answer.prayer),
        reflection_question: text(answer.reflection_question),
        phrase: text(answer.phrase),
      };
      const complete =
        pairs.length === 3 &&
        dialogue.length === 3 &&
        Object.values(candidate).every((v) => (typeof v === 'string' ? v !== '' : true));
      if (complete) reflection = candidate;
    } catch (error) {
      // Failed call or invalid JSON: the rows of this variant get the gospel alone.
    }
  }
  return { json: { ...variant, reflection, aiOk: reflection !== null } };
});

// Builds one item per variant. English variants with a valid reflection get an
// Ollama request for the vocabulary box, made from the English gospel text and
// the reflection of that variant.
const { config } = $('Schedule Check').first().json;
const model = config.ollama_model || 'gemma4:12b';
const { gospels } = $('Build Gospels').first().json;

// The schema makes Ollama write the answer in this exact shape.
const string = { type: 'string' };
const format = {
  type: 'object',
  properties: {
    vocabulary: {
      type: 'array',
      minItems: 5,
      maxItems: 5,
      items: {
        type: 'object',
        properties: { word: string, meaning_es: string, example: string },
        required: ['word', 'meaning_es', 'example'],
      },
    },
  },
  required: ['vocabulary'],
};

return $input.all().map(({ json: variant }) => {
  const wantsVocabulary = variant.language === 'en' && variant.aiOk;
  if (!wantsVocabulary) return { json: { key: variant.key, wantsVocabulary } };

  const r = variant.reflection;
  const prompt = [
    'You help a Spanish speaker who is learning English.',
    `From the gospel passage and the reflection below, choose the 5 most difficult English words or expressions for a learner at CEFR level ${variant.level}.`,
    'Choose only words that appear in the passage or in the reflection. Do not choose names of people or places.',
    'For each one, give its meaning in Spanish and one short example sentence in English.',
    'Answer with JSON only, in this shape: {"vocabulary": [{"word": "...", "meaning_es": "...", "example": "..."}]}',
    '',
    'Passage:',
    gospels.en.text,
    '',
    'Reflection:',
    ...r.dialogue.flatMap((p) => [p.question, p.answer]),
    r.application,
    r.action,
    r.prayer,
    r.reflection_question,
    r.phrase,
  ].join('\n');

  return {
    json: {
      key: variant.key,
      wantsVocabulary,
      request: { model, prompt, format, stream: false, think: false },
    },
  };
});

// Adds the vocabulary list to each variant. It stays empty for Spanish variants,
// for variants without reflection, and when the Ollama call failed or returned
// invalid JSON.
const text = (v) => (typeof v === 'string' ? v.trim() : '');

// The loop returns one result per variant, in the same order.
const requests = $('Vocabulary Prompts').all();
const results = $input.all();
const inOrder = results.length === requests.length;

return $('Apply Reflections')
  .all()
  .map(({ json }, i) => {
    let vocabulary = [];
    if (inOrder && requests[i].json.wantsVocabulary) {
      try {
        const answer = JSON.parse(results[i].json.response) ?? {};
        vocabulary = (Array.isArray(answer.vocabulary) ? answer.vocabulary : [])
          .map((v) => ({
            word: text(v?.word),
            meaning_es: text(v?.meaning_es),
            example: text(v?.example),
          }))
          .filter((v) => v.word && v.meaning_es && v.example)
          .slice(0, 5);
      } catch (error) {
        // Failed call or invalid JSON: no vocabulary box.
      }
    }
    return { json: { ...json, vocabulary } };
  });

// Renders one HTML email per row from the gospel of each of its languages, the
// apologetic note of the language, and the reflection and the vocabulary of its
// variants, with the labels in the block's language. Styles are inline, so a
// client that drops <style> still shows the full layout. <style> holds only the
// rule that reduces the side padding on phones.
const WIDTH = 760; // max width of the column, and fixed width in Outlook

const LABELS = {
  en: {
    locale: 'en-US',
    subject: 'Gospel of the day',
    gospel: 'Gospel',
    note: 'Apologetic note',
    dialogue: 'Questions and answers',
    application: 'For your life',
    action: 'Today',
    prayer: 'Prayer',
    question: 'To think about',
    phrase: 'To remember',
    vocabulary: 'Vocabulary',
    footer:
      'The gospel text comes from the Evangelizo feed. The note and the reflection are written by an AI and are not church teaching.',
  },
  es: {
    locale: 'es-CO',
    subject: 'Evangelio del día',
    gospel: 'Evangelio',
    note: 'Nota apologética',
    dialogue: 'Preguntas y respuestas',
    application: 'Para tu vida',
    action: 'Hoy',
    prayer: 'Oración',
    question: 'Para pensar',
    phrase: 'Para recordar',
    vocabulary: 'Vocabulario',
    footer:
      'El texto del evangelio viene del servicio de Evangelizo. La nota y la reflexión las escribe una IA y no son enseñanza de la Iglesia.',
  },
};

// One palette and two type families for the whole email: a serif for the words
// of the gospel and the prayer, a sans-serif for the explanation.
const SERIF = "font-family:Georgia,'Times New Roman',Times,serif;";
const SANS = "font-family:-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;";
const INK = '#2b2622';
const TEXT = '#4a433c';
const MUTED = '#8c8378';
const ACCENT = '#9a6b2f';
const LINE = '#ebe4d8';
const PAPER = '#f4f0e8';
const SHEET = '#fffdf9';
const TINT = '#f8f3e9';

const esc = (v) =>
  String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
// Escaped text with one <br> per line break.
const multiline = (v) => String(v ?? '').split('\n').map((l) => esc(l.trim())).filter(Boolean).join('<br>');

const { rows } = $('Build Plan').first().json;
const { gospels } = $('Build Gospels').first().json;
const { notes } = $('Apply Apologetics').first().json;
const variants = {};
for (const { json } of $('Apply Vocabulary').all()) variants[json.key] = json;

const now = new Date();

// A section is one row of the sheet. Sections are separated by a hairline.
const section = (inner, style = '') => `
          <tr><td class="px-inner" style="padding:30px 28px;border-top:1px solid ${LINE};${style}">${inner}
          </td></tr>`;
const label = (text, align = 'left') =>
  `
            <div style="${SANS}font-size:11px;line-height:16px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:${ACCENT};text-align:${align};">${text}</div>`;

// One full block: header, gospel, apologetic note, reflection and, in English,
// vocabulary.
const block = (gospel, variant, note) => {
  const t = LABELS[gospel.language];
  const day = new Intl.DateTimeFormat(t.locale, { timeZone: 'America/Bogota', dateStyle: 'full' }).format(now);
  const date = day.charAt(0).toUpperCase() + day.slice(1);

  const header = `
          <tr><td class="px-inner" align="center" style="padding:40px 28px 34px 28px;">${label(t.subject, 'center')}
            <div style="${SERIF}font-size:27px;line-height:35px;color:${INK};text-align:center;padding-top:14px;">${esc(gospel.liturgicalDay)}</div>
            <div style="${SANS}font-size:13px;line-height:20px;color:${MUTED};text-align:center;padding-top:8px;">${esc(date)}</div>
          </td></tr>`;

  const paragraphs = gospel.text
    .split('\n')
    .map((p) => `
            <div style="${SERIF}font-size:19px;line-height:31px;color:${INK};padding-top:14px;">${esc(p)}</div>`)
    .join('');
  const gospelSection = section(
    `${label(`${t.gospel} &nbsp;·&nbsp; ${esc(gospel.reference)}`)}${paragraphs}
            <div style="${SANS}font-size:11px;line-height:17px;color:${MUTED};padding-top:20px;">${esc(gospel.attribution)}</div>`,
  );

  // The note has two lines, context and then meaning. It is shown only on the
  // days the model found it needed, with or without a reflection.
  const noteSection =
    note?.ok && note.needed
      ? section(
          `${label(t.note)}
            <div style="${SANS}font-size:16px;line-height:26px;color:${TEXT};padding-top:14px;">${esc(note.context)}</div>
            <div style="${SANS}font-size:16px;line-height:26px;color:${TEXT};padding-top:10px;">${esc(note.meaning)}</div>`,
        )
      : '';

  const r = variant?.aiOk ? variant.reflection : null;
  let reflection = '';
  if (r) {
    const pairs = r.dialogue
      .map(
        (p) => `
            <div style="${SERIF}font-size:18px;line-height:27px;font-style:italic;color:${INK};padding-top:20px;">${esc(p.question)}</div>
            <div style="${SANS}font-size:16px;line-height:26px;color:${TEXT};padding-top:6px;">${esc(p.answer)}</div>`,
      )
      .join('');
    reflection =
      section(`${label(t.dialogue)}${pairs}`) +
      section(
        `${label(t.application)}
            <div style="${SANS}font-size:16px;line-height:26px;color:${TEXT};padding-top:14px;">${esc(r.application)}</div>
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:22px;">
              <tr><td style="background:${TINT};border-left:3px solid ${ACCENT};padding:16px 18px;">${label(t.action)}
                <div style="${SANS}font-size:16px;line-height:25px;color:${INK};padding-top:6px;">${esc(r.action)}</div>
              </td></tr>
            </table>`,
      ) +
      section(
        `${label(t.prayer, 'center')}
            <div style="${SERIF}font-size:18px;line-height:31px;font-style:italic;color:${INK};text-align:center;padding-top:14px;">${multiline(r.prayer)}</div>`,
        `background:${TINT};`,
      ) +
      section(
        `${label(t.question, 'center')}
            <div style="${SANS}font-size:16px;line-height:26px;color:${TEXT};text-align:center;padding-top:12px;">${esc(r.reflection_question)}</div>
            <div style="font-size:14px;line-height:14px;color:${ACCENT};text-align:center;padding:26px 0 24px 0;">&#10022;</div>${label(t.phrase, 'center')}
            <div style="${SERIF}font-size:23px;line-height:33px;color:${INK};text-align:center;padding-top:12px;">${esc(r.phrase)}</div>`,
      );
  }

  const words = (gospel.language === 'en' ? variant?.vocabulary ?? [] : [])
    .map(
      (v, i) => `
            <div style="${i ? `border-top:1px solid ${LINE};margin-top:14px;` : ''}padding-top:14px;">
              <div style="${SANS}font-size:16px;line-height:24px;color:${INK};"><b>${esc(v.word)}</b> <span style="color:${MUTED};">&nbsp;—&nbsp;</span> ${esc(v.meaning_es)}</div>
              <div style="${SERIF}font-size:15px;line-height:23px;font-style:italic;color:${MUTED};padding-top:2px;">${esc(v.example)}</div>
            </div>`,
    )
    .join('');
  const vocabularySection = words ? section(`${label(t.vocabulary)}${words}`) : '';

  // Each block is its own sheet of paper.
  return `
        <tr><td style="padding:0 0 20px 0;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${SHEET};border:1px solid ${LINE};border-top:3px solid ${ACCENT};">${header}${gospelSection}${noteSection}${reflection}${vocabularySection}
          </table>
        </td></tr>`;
};

return rows.map((row) => {
  // Blocks in a fixed order: English first, Spanish below. A language whose
  // gospel is not ok gives no block.
  const blockLanguages = (row.language === 'both' ? ['en', 'es'] : [row.language]).filter(
    (language) => gospels[language]?.ok,
  );
  const variantOf = (language) => variants[row.variantKeys.find((key) => key.startsWith(`${language}|`))];

  const blocks = blockLanguages.map((language) => block(gospels[language], variantOf(language), notes[language])).join('');
  const footer = blockLanguages.map((language) => `<div style="padding-bottom:6px;">${LABELS[language].footer}</div>`).join('');

  const reference = gospels[blockLanguages[0]]?.reference ?? '';
  const subject = `${blockLanguages.map((language) => LABELS[language].subject).join(' / ')} — ${reference}`;

  const html = `<!DOCTYPE html>
<html lang="${blockLanguages[0] ?? 'en'}">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(subject)}</title>
<style>
  @media (max-width:480px) {
    .px-outer { padding-left:4px !important; padding-right:4px !important; }
    .px-inner { padding-left:18px !important; padding-right:18px !important; }
  }
</style>
</head>
<body style="margin:0;padding:0;background:${PAPER};">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${PAPER};">
    <tr><td class="px-outer" align="center" style="padding:24px 10px;">
      <!--[if mso]><table role="presentation" width="${WIDTH}" align="center" cellpadding="0" cellspacing="0"><tr><td><![endif]-->
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:${WIDTH}px;">${blocks}
        <tr><td class="px-inner" style="padding:4px 24px 20px 24px;${SANS}font-size:11px;line-height:17px;color:${MUTED};text-align:center;">${footer}</td></tr>
      </table>
      <!--[if mso]></td></tr></table><![endif]-->
    </td></tr>
  </table>
</body>
</html>`;

  return {
    json: {
      rowNumber: row.rowNumber,
      recipients: row.recipients,
      bcc: row.recipients.join(', '),
      subject,
      html,
      blockCount: blockLanguages.length,
    },
  };
});
